import logging
from taf.collectors.aashell_log.collector import AaShellLogCollector
from taf.collectors.aashell_cli.factory import AaShellCliFactory
from taf.collectors.core.templates.dynamic_class_creation import Creating
from taf.collectors.core import NamedComponentFactory

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class AaShellLogFactory(Creating("tool_executor", "SshExecutor", "executor"),
                        Creating("file_getter", "SshFileGetter", "executor"),
                        NamedComponentFactory):
    """
    factory to create aashell_log collectors
    """

    def create(self, configuration, existing_arguments):
        """
        Create a aashell_log collector

        :param dict configuration:
                collection of configuration parameters for the object to be created and other
                objects, that might have to be created as prerequisites
        :param dict existing_arguments:
                existing arguments for the final constructor call, that don't need to be created
                (dict with constructor parameter name as key and argument value as value)

        :return: AaShellLogCollector
        """
        resulting_arguments = {}
        configuration['executor'] = AaShellCliFactory.get_executor_of_aashell_cli(existing_arguments["tool"])
        self._build_arguments(configuration=configuration,
                              existing_arguments=existing_arguments,
                              resulting_arguments=resulting_arguments)
        return AaShellLogCollector(**resulting_arguments)

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        super(AaShellLogFactory, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        for parameter_name in ["options", "target_file_name", "timeout"]:
            if parameter_name in configuration:
                resulting_arguments[parameter_name] = configuration[parameter_name]
        resulting_arguments["tool"] = existing_arguments["tool"]
